from collections import deque

def transitions(state):

    approved, executed = state

    if not approved and not executed:
        yield (True, False)

    if approved and not executed:
        yield (True, True)

    # Approval may be revoked
    # before execution.
    if approved and not executed:
        yield (False, False)

def check_safety():

    initial = (False, False)

    queue = deque([initial])
    visited = set()

    while queue:

        state = queue.popleft()

        if state in visited:
            continue

        visited.add(state)

        approved, executed = state

        assert not executed or approved, (
            "Unauthorized execution reachable"
        )

        queue.extend(
            transitions(state)
        )

    return len(visited)

print(check_safety())

